# 탄자니아 탭 보강 (like Lao v3.18/v3.22): 쪽마다 '더 알아보기' 상자 + '이럴 때 이렇게 말해요', 새 소분류 '여행·생활 준비'.
# info_tz.py imports this at the end. Facts that change (prices, rules) carry '바뀔 수 있어요'.
import swrd
from info_tz import OV
def _L(lo, rd=None):
    rd = rd or OV.get(lo.rstrip('.!?')) or swrd.reading(lo)
    return f'<span class="lo">{lo}</span> <span class="r">{rd}</span>'
def card(h, body):
    b = ('<ul>' + ''.join(f'<li>{x}</li>' for x in body) + '</ul>') if isinstance(body, list) else ''.join(f'<p>{x}</p>' for x in body.split('\n'))
    return f'<div class="card"><h4>{h}</h4>{b}</div>'
def phr(rows):
    return '<div class="phr"><div class="ph-t">이럴 때 이렇게 말해요</div>' + ''.join(f'<div>{_L(a)}<span class="m">{b}</span></div>' for a, b in rows) + '</div>'
def more(cards, warn=None, ph=None):
    s = '<h3 class="more">더 알아보기</h3><div class="cards">' + ''.join(card(h, b) for h, b in cards)
    if warn: s += f'<div class="warn">{warn}</div>'
    s += '</div>'
    return s + (phr(ph) if ph else '')
